#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
TMP_CHECKS="$(mktemp -d "${TMPDIR:-/tmp}/salary-ai-checks.XXXXXX")"
trap 'rm -rf "$TMP_CHECKS"' EXIT
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryCodexQuotaClient.swift tests/SalaryAIQuotaChecks.swift -o "$TMP_CHECKS/parsers"
"$TMP_CHECKS/parsers"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryAIQuotaStore.swift boringNotch/Salary/Codenotch/UsagePolicy.swift tests/SalaryAIQuotaStoreChecks.swift -o "$TMP_CHECKS/store"
"$TMP_CHECKS/store"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryCodexQuotaClient.swift tests/SalaryCodexQuotaClientChecks.swift -o "$TMP_CHECKS/client"
"$TMP_CHECKS/client"
clang tests/fixtures/QuotaFakeCLI.c -o "$TMP_CHECKS/fake-cli"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryCodexQuotaClient.swift tests/SalaryQuotaProcessChecks.swift -o "$TMP_CHECKS/process"
"$TMP_CHECKS/process" "$TMP_CHECKS/fake-cli"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryCodexQuotaClient.swift boringNotch/Salary/SalaryAGYQuotaClient.swift tests/SalaryAGYUsageChecks.swift -o "$TMP_CHECKS/agy"
"$TMP_CHECKS/agy"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryCodexQuotaClient.swift boringNotch/Salary/SalaryAGYQuotaClient.swift tests/AGYSafeDiagnostics.swift tests/AGYSafeDiagnosticChecks.swift -o "$TMP_CHECKS/agy-diagnostic"
"$TMP_CHECKS/agy-diagnostic"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryAIQuotaStore.swift boringNotch/Salary/SalaryCodexQuotaClient.swift boringNotch/Salary/SalaryAGYQuotaClient.swift boringNotch/Salary/SalaryAIQuotaConnections.swift boringNotch/Salary/Codenotch/*.swift tests/SalaryQuotaConnectionChecks.swift -o "$TMP_CHECKS/connections"
"$TMP_CHECKS/connections" "$TMP_CHECKS/fake-cli"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryAIQuotaStore.swift boringNotch/Salary/Codenotch/UsagePolicy.swift tests/SalaryQuotaAcceptanceChecks.swift -o "$TMP_CHECKS/acceptance"
"$TMP_CHECKS/acceptance"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryAIQuotaStore.swift boringNotch/Salary/SalaryCodexQuotaClient.swift boringNotch/Salary/SalaryAGYQuotaClient.swift boringNotch/Salary/SalaryAIQuotaConnections.swift boringNotch/Salary/Codenotch/*.swift tests/SalaryCodenotchProviderChecks.swift -o "$TMP_CHECKS/codenotch"
"$TMP_CHECKS/codenotch"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryAIQuotaStore.swift boringNotch/Salary/Codenotch/*.swift tests/SalaryCodenotchHTTPChecks.swift -o "$TMP_CHECKS/codenotch-http"
"$TMP_CHECKS/codenotch-http"
swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryAIQuotaStore.swift boringNotch/Salary/SalaryCodexQuotaClient.swift boringNotch/Salary/SalaryAGYQuotaClient.swift boringNotch/Salary/SalaryAIQuotaConnections.swift boringNotch/Salary/Codenotch/*.swift tests/SalaryQuotaRefreshPolicyChecks.swift -o "$TMP_CHECKS/refresh-policy"
"$TMP_CHECKS/refresh-policy"

swiftc -module-cache-path "$TMP_CHECKS/modules" boringNotch/Salary/SalaryAIQuota.swift boringNotch/Salary/SalaryAIQuotaStore.swift boringNotch/Salary/SalaryCodexQuotaClient.swift boringNotch/Salary/SalaryAGYQuotaClient.swift boringNotch/Salary/SalaryAIQuotaConnections.swift boringNotch/Salary/Codenotch/*.swift tests/SalaryQuotaExitHelper.swift -o "$TMP_CHECKS/exit-helper"
swiftc -parse-as-library -module-cache-path "$TMP_CHECKS/modules" tests/SalaryQuotaExitChecks.swift -o "$TMP_CHECKS/exit-check"
"$TMP_CHECKS/exit-check" "$TMP_CHECKS/fake-cli" "$TMP_CHECKS/exit-helper"
